// Turns an old-layout revision of packages/envoy/AGENTS.md (the Envoy guide) and
// packages/envoy/cmd/dispatch/README.md (the Dispatch server README) into the new layout
// (INFRA-631), so the change is regenerated by a script and never re-done by hand.
//
//   bun .legion/INFRA-631/restructure.ts (--strict|--lenient) [--structural-only]
//     [--line-breaks <path to semantic-line-breaks.ts>] [<input.md> <output.md>]...
//
// With no file pairs it rewrites the workspace's two files in place. A file is recognised by its
// first line. Steps, in order:
//
//   1. each named table becomes a list, one item per row (TABLES);
//   2. the words that pointed at a converted table say "list" (REWORDINGS);
//   3. two named statement edits (STATEMENT_EDITS);
//   4. the README migration log gets the rule that stops it growing (MIGRATION_NOTE);
//   5. each file gets the layout instruction under its title (HEAD_NOTES);
//   6. items longer than one screen are split into sibling items (SPLITS);
//   7. scripts/semantic-line-breaks.ts --write re-lays out the result (whitespace only);
//   8. the same script checks it.
//
// Every edit is anchored by text, never by line number. --strict fails, writing nothing, on any
// anchor that is missing or not unique, on any refusal of step 7 and on any finding of step 8;
// --lenient warns and skips the edit, so an open pull request can port its old-layout files onto
// the new layout. When step 7 refuses a file (its re-layout would render differently), --lenient
// writes that output with the result of steps 1-6, warns with the refused block's line in that
// output, skips step 8 for it, writes the other outputs as usual and exits 2.
// --structural-only writes the result of steps 1-6, the intermediate commit a reviewer reads.
import { spawnSync } from "node:child_process";
import { mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";

type Guide = "agents" | "readme";

const REPO_ROOT = resolve(import.meta.dir, "../..");

const GUIDES: Record<Guide, { title: string; path: string }> = {
  agents: { title: "# Envoy Package", path: "packages/envoy/AGENTS.md" },
  readme: { title: "# Dispatch HTTP server", path: "packages/envoy/cmd/dispatch/README.md" },
};

const USAGE =
  "usage: bun .legion/INFRA-631/restructure.ts (--strict|--lenient) [--structural-only] " +
  "[--line-breaks <semantic-line-breaks.ts>] [<input.md> <output.md>]...\n";

// ---------------------------------------------------------------------------------------------
// The named edits. Each is data: an id, the file, its anchor text and a one-line reason.
// ---------------------------------------------------------------------------------------------

interface TableConversion {
  id: string;
  guide: Guide;
  /** The heading the table sits under, as written. */
  section: string;
  /** The header row's cell texts, which identify the table; its body rows may change freely. */
  header: string[];
  /** Words of the paragraph just before the table, for two tables that share a header. */
  follows?: string;
  /** The paragraph that replaces the header row and names what each item holds. */
  intro: string;
  /** The item's first line, after `- `, from the row's cells by header name. */
  key: (cell: (column: string) => string) => string;
  /** The column whose text follows as the item's second paragraph. */
  prose: string;
  reason: string;
}

