interface Rewording {
  id: string;
  guide: Guide;
  /** Matched with any run of whitespace standing for each space. */
  find: string;
  replace: string;
  /** Rewrite every occurrence (at least one) instead of requiring exactly one. */
  every?: true;
  /** The split this citation names the item of; when that split is skipped, so is this. */
  after?: string;
  reason: string;
}

