// ---------------------------------------------------------------------------------------------
// Applying the edits.
// ---------------------------------------------------------------------------------------------

interface Problem {
  id: string;
  anchor: string;
  message: string;
  /** The edit was made all the same; the problem is a warning about the input. */
  applied?: true;
}

const ITEM_START = /^([ \t]*)([-*+]|\d{1,9}[.)])([ \t]+)/;
const HEADING = /^#{1,6}(?:[ \t]|$)/;
const FENCE = /^[ \t]*(`{3,}|~{3,})/;
const DELIMITER_ROW = /^[ \t]*\|?[ \t]*:?-+:?[ \t]*(?:\|[ \t]*:?-+:?[ \t]*)*\|?[ \t]*$/;
const TABLE_LINE = /^ {0,3}\|/;
const CLOSERS = ")]\"'*_”’";

function fold(text: string): string {
  return text.replace(/\s+/g, " ").trim();
}

/** Every match of the anchor, any run of whitespace standing for each of its spaces. */
function matches(text: string, anchor: string): RegExpExecArray[] {
  const words = anchor.trim().split(/\s+/);
  const pattern = words.map((word) => word.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("\\s+");
  return [...text.matchAll(new RegExp(pattern, "g"))];
}

/** Why an anchor that must be unique was not: it matched `count` times. */
function anchorMiss(count: number): string {
  return count === 0 ? "missing" : `${count} matches`;
}

function isBlank(line: string | undefined): boolean {
  return line === undefined || line.trim() === "";
}

/** The cells of a table row: split at each `|` not escaped, the outer pipes dropped, trimmed. */
function rowCells(line: string): string[] {
  let row = line.trim();
  if (row.startsWith("|")) row = row.slice(1);
  if (row.endsWith("|") && !row.endsWith("\\|")) row = row.slice(0, -1);
  return row.split(/(?<!\\)\|/).map((cell) => cell.trim());
}

/**
 * Inside a code span a table cell's `\|` is GFM's escape for `|`, which a list item would render
 * literally, so it becomes `|`; a `\|` outside code renders as `|` anywhere and stays.
 */
function unescapeCodePipes(cell: string): string {
  let out = "";
  let at = 0;
  while (at < cell.length) {
    if (cell[at] === "\\") {
      out += cell.slice(at, at + 2);
      at += 2;
      continue;
    }
    if (cell[at] !== "`") {
      out += cell[at];
      at++;
      continue;
    }
    let run = 0;
    while (cell[at + run] === "`") run++;
    const fence = "`".repeat(run);
    let close = cell.indexOf(fence, at + run);
    while (close !== -1 && cell[close + run] === "`") {
      let end = close;
      while (cell[end] === "`") end++;
      close = cell.indexOf(fence, end);
    }
    if (close === -1) {
      out += fence;
      at += run;
      continue;
    }
    out += cell.slice(at, close + run).replaceAll("\\|", "|");
    at = close + run;
  }
  return out;
}

interface FoundTable {
  first: number;
  last: number;
  section: string;
  header: string[];
  before: string;
}

/** Every pipe table outside fences, with the heading it sits under and the paragraph before it. */
function findTables(lines: readonly string[]): FoundTable[] {
  const tables: FoundTable[] = [];
  let section = "";
  let fence: string | undefined;
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index] ?? "";
    const run = FENCE.exec(line)?.[1];
    if (fence !== undefined) {
      if (run?.startsWith(fence) && line.trim() === run) fence = undefined;
      continue;
    }
    if (run !== undefined) {
      fence = run;
      continue;
    }
    if (HEADING.test(line)) section = line.trim();
    if (!TABLE_LINE.test(line) || !DELIMITER_ROW.test(lines[index + 1] ?? "")) continue;
    let last = index + 1;
    while (TABLE_LINE.test(lines[last + 1] ?? "")) last++;
    let start = index;
    while (start > 0 && isBlank(lines[start - 1])) start--;
    const paragraph: string[] = [];
    while (start > 0 && !isBlank(lines[start - 1]) && !HEADING.test(lines[start - 1] ?? "")) {
      paragraph.unshift(lines[--start] ?? "");
    }
    tables.push({
      first: index,
      last,
      section,
      header: rowCells(line),
      before: fold(paragraph.join(" ")),
    });
    index = last;
  }
  return tables;
}

function sameHeader(a: readonly string[], b: readonly string[]): boolean {
  return a.length === b.length && a.every((cell, n) => cell === b[n]);
}

/** The table as list lines: the intro paragraph, then one item per row. */
function tableAsList(
  lines: readonly string[],
  table: FoundTable,
  edit: TableConversion
): string[] | string {
  const out = [edit.intro];
  for (let index = table.first + 2; index <= table.last; index++) {
    const cells = rowCells(lines[index] ?? "").map(unescapeCodePipes);
    if (cells.length !== table.header.length) {
      return `row ${index - table.first - 1} has ${cells.length} cells, the header ${table.header.length}`;
    }
    const cell = (column: string): string => {
      const at = table.header.indexOf(column);
      if (at === -1) throw new Error(`${edit.id}: no column ${column}`);
      return cells[at] ?? "";
    };
    out.push("", `- ${edit.key(cell)}`);
    const prose = cell(edit.prose);
    if (prose !== "") out.push("", `  ${prose}`);
  }
  return out;
}

function convertTables(
  text: string,
  guide: Guide,
  problems: Problem[],
  warnings: string[]
): string {
  const lines = text.split("\n");
  const tables = findTables(lines);
  const replacements: { table: FoundTable; list: string[] }[] = [];
  for (const edit of TABLES.filter((table) => table.guide === guide)) {
    const anchor = `${edit.section} | ${edit.header.join(" | ")} |${edit.follows ? ` after "${edit.follows}"` : ""}`;
    const found = tables.filter(
      (table) =>
        table.section === edit.section &&
        sameHeader(table.header, edit.header) &&
        (edit.follows === undefined || table.before.includes(edit.follows))
    );
    if (found.length !== 1) {
      problems.push({ id: edit.id, anchor, message: anchorMiss(found.length) });
      continue;
    }
    const table = found[0] as FoundTable;
    const list = tableAsList(lines, table, edit);
    if (typeof list === "string") {
      problems.push({ id: edit.id, anchor, message: list });
      continue;
    }
    replacements.push({ table, list });
  }
  for (const table of tables) {
    const named =
      TABLES.some(
        (edit) =>
          edit.guide === guide &&
          edit.section === table.section &&
          sameHeader(edit.header, table.header)
      ) ||
      KEPT_TABLES.some(
        (kept) =>
          kept.guide === guide &&
          kept.section === table.section &&
          sameHeader(kept.header, table.header)
      );
    if (!named)
      warnings.push(
        `a table no edit names stays as it is: line ${table.first + 1}, ${table.section}`
      );
  }
  // Bottom-up, so earlier line numbers stay valid.
  replacements.sort((a, b) => b.table.first - a.table.first);
  for (const { table, list } of replacements) {
    const block = [...list];
    if (!isBlank(lines[table.first - 1])) block.unshift("");
    if (!isBlank(lines[table.last + 1]) && table.last + 1 < lines.length) block.push("");
    lines.splice(table.first, table.last - table.first + 1, ...block);
  }
  return lines.join("\n");
}

function applyRewordings(
  text: string,
  edits: readonly Rewording[],
  guide: Guide,
  problems: Problem[]
): string {
  let out = text;
  for (const edit of edits.filter((candidate) => candidate.guide === guide)) {
    const found = matches(out, edit.find);
    if (found.length === 0 || (found.length > 1 && !edit.every)) {
      problems.push({ id: edit.id, anchor: edit.find, message: anchorMiss(found.length) });
      continue;
    }
    for (const match of found.reverse()) {
      out = out.slice(0, match.index) + edit.replace + out.slice(match.index + match[0].length);
    }
  }
  return out;
}

function addMigrationNote(text: string, guide: Guide, problems: Problem[]): string {
  const note = MIGRATION_NOTE;
  if (note.guide !== guide) return text;
  const found = matches(text, note.anchor);
  const match = found[0];
  if (found.length !== 1 || match === undefined) {
    problems.push({ id: note.id, anchor: note.anchor, message: anchorMiss(found.length) });
    return text;
  }
  if (!(match.index === 0 || text.slice(0, match.index).endsWith("\n\n"))) {
    problems.push({ id: note.id, anchor: note.anchor, message: "does not start a paragraph" });
    return text;
  }
  const end = text.indexOf(`\n${note.until}\n`, match.index);
  if (end === -1) {
    problems.push({ id: note.id, anchor: note.until, message: "missing after the anchor" });
    return text;
  }
  const notes = new Map<string, string>();
  for (const [, number = "", suffix] of text
    .slice(match.index, end)
    .matchAll(/`(0\d{3})(_[a-z0-9_]+)?`/g)) {
    const name = `${number}${suffix ?? ""}`;
    if (number > note.through) {
      if (!notes.has(number) || suffix !== undefined) {
        notes.set(number, `the log notes migration \`${name}\`, above \`${note.through}\``);
      }
    } else if (suffix !== undefined && !MAIN_MIGRATIONS.includes(name)) {
      const taken = MAIN_MIGRATIONS.find((migration) => migration.startsWith(`${number}_`));
      notes.set(
        name,
        `the log notes migration \`${name}\`, but main's migration ${number} is \`${taken}\`, so that migration needs a new number`
      );
    }
  }
  for (const [key, message] of [...notes].sort(([a], [b]) => a.localeCompare(b))) {
    problems.push({
      id: note.id,
      anchor: `\`${key}\``,
      message: `${message}; move that note into the header comment of its migration's .up.sql`,
      applied: true,
    });
  }
  return `${text.slice(0, match.index)}${note.text(note.through).join("\n")}\n\n${text.slice(match.index)}`;
}

function addHeadNote(text: string, guide: Guide, problems: Problem[]): string {
  const note = HEAD_NOTES.find((candidate) => candidate.guide === guide);
  if (note === undefined) return text;
  const lines = text.split("\n");
  let first = 1;
  while (first < lines.length && isBlank(lines[first])) first++;
  let last = first;
  while (last + 1 < lines.length && !isBlank(lines[last + 1])) last++;
  if (!fold(lines.slice(first, last + 1).join(" ")).endsWith(fold(note.after))) {
    problems.push({
      id: note.id,
      anchor: note.after,
      message: "not the end of the first paragraph under the title",
    });
    return text;
  }
  lines.splice(last + 1, 0, "", ...headNote(guide));
  return lines.join("\n");
}

/** The line that opens the list item holding the given line, or a reason there is none. */
function itemStartAbove(lines: readonly string[], from: number): number | string {
  for (let index = from; index >= 0; index--) {
    const line = lines[index] ?? "";
    if (ITEM_START.test(line)) return index;
    if (HEADING.test(line)) return "not inside a list item";
    if (!isBlank(line) && !/^[ \t]/.test(line) && isBlank(lines[index - 1]))
      return "not inside a list item";
  }
  return "not inside a list item";
}

function applySplits(text: string, guide: Guide, problems: Problem[]): string {
  let out = text;
  for (const split of SPLITS.filter((candidate) => candidate.guide === guide)) {
    const found = matches(out, split.anchor);
    const match = found[0];
    if (found.length !== 1 || match === undefined) {
      problems.push({ id: split.id, anchor: split.anchor, message: anchorMiss(found.length) });
      continue;
    }
    let space = match.index;
    while (space > 0 && /[ \t\n]/.test(out[space - 1] ?? "")) space--;
    let mark = space - 1;
    while (mark > 0 && CLOSERS.includes(out[mark] ?? "")) mark--;
    if (space === match.index || !".!?".includes(out[mark] ?? "")) {
      problems.push({ id: split.id, anchor: split.anchor, message: "does not start a sentence" });
      continue;
    }
    const lines = out.slice(0, space).split("\n");
    const start = itemStartAbove(lines, lines.length - 1);
    if (typeof start === "string") {
      problems.push({ id: split.id, anchor: split.anchor, message: start });
      continue;
    }
    const [, indent, marker, gap] = ITEM_START.exec(lines[start] ?? "") ?? [];
    out = `${out.slice(0, space)}\n\n${indent}${marker}${gap}${out.slice(match.index)}`;
  }
  return out;
}

/** Steps 1-6 on one file's text. */
function restructure(text: string, guide: Guide, problems: Problem[], warnings: string[]): string {
  let out = convertTables(text, guide, problems, warnings);
  out = applyRewordings(out, REWORDINGS, guide, problems);
  out = applyRewordings(out, STATEMENT_EDITS, guide, problems);
  out = addMigrationNote(out, guide, problems);
  out = addHeadNote(out, guide, problems);
  out = applySplits(out, guide, problems);
  const skipped = new Set(problems.map((problem) => problem.id));
  for (const citation of SPLIT_CITATIONS) {
    if (citation.guide === guide && citation.after !== undefined && skipped.has(citation.after)) {
      problems.push({
        id: citation.id,
        anchor: citation.find,
        message: `${citation.after} skipped`,
      });
    }
  }
  const citations = SPLIT_CITATIONS.filter(
    (citation) => citation.after === undefined || !skipped.has(citation.after)
  );
  return applyRewordings(out, citations, guide, problems);
}

// ---------------------------------------------------------------------------------------------
// Steps 7 and 8, and the command line.
// ---------------------------------------------------------------------------------------------

function runLineBreaks(
  lineBreaks: string,
  args: string[]
): { status: number; stdout: string; stderr: string } {
  const result = spawnSync(process.execPath, [lineBreaks, ...args], { encoding: "utf8" });
  if (result.error) throw result.error;
  return { status: result.status ?? 1, stdout: result.stdout, stderr: result.stderr };
}

function guideOf(text: string): Guide | undefined {
  const title = text.slice(0, text.indexOf("\n") === -1 ? undefined : text.indexOf("\n"));
  return (Object.keys(GUIDES) as Guide[]).find((guide) => GUIDES[guide].title === title);
}

/** Ends the run with an exit status, once the scratch directory is removed. */
class Failure extends Error {
  constructor(
    message: string,
    readonly status: number
  ) {
    super(message);
  }
}

function fail(message: string, status: number): never {
  throw new Failure(message, status);
}

async function main(argv: string[]): Promise<number> {
  let strict: boolean | undefined;
  let structuralOnly = false;
  let lineBreaks = join(REPO_ROOT, "scripts/semantic-line-breaks.ts");
  const paths: string[] = [];
  for (let index = 0; index < argv.length; index++) {
    const arg = argv[index] ?? "";
    if (arg === "--strict" || arg === "--lenient") {
      if (strict !== undefined) fail(USAGE, 2);
      strict = arg === "--strict";
    } else if (arg === "--structural-only") {
      structuralOnly = true;
    } else if (arg === "--line-breaks") {
      lineBreaks = resolve(argv[++index] ?? fail(USAGE, 2));
    } else if (arg.startsWith("-")) {
      fail(USAGE, 2);
    } else {
      paths.push(resolve(arg));
    }
  }
  if (strict === undefined || paths.length % 2 !== 0) fail(USAGE, 2);
  const pairs: [string, string][] = [];
  if (paths.length === 0) {
    for (const guide of Object.keys(GUIDES) as Guide[]) {
      const path = join(REPO_ROOT, GUIDES[guide].path);
      pairs.push([path, path]);
    }
  }
  for (let index = 0; index < paths.length; index += 2) {
    pairs.push([paths[index] ?? "", paths[index + 1] ?? ""]);
  }

  const scratch = await mkdtemp(join(tmpdir(), "infra-631-restructure-"));
  try {
    const results: { output: string; text: string }[] = [];
    let failed = false;
    let refused = false;
    for (const [n, [input, output]] of pairs.entries()) {
      const text = await readFile(input, "utf8");
      const guide = guideOf(text);
      if (guide === undefined) {
        fail(
          `${input}: not the Envoy guide or the Dispatch README (its first line is neither "${GUIDES.agents.title}" nor "${GUIDES.readme.title}")\n`,
          2
        );
      }
      const problems: Problem[] = [];
      const warnings: string[] = [];
      let next = restructure(text, guide, problems, warnings);
      for (const warning of warnings) process.stderr.write(`${input}: warning: ${warning}\n`);
      for (const problem of problems) {
        const level = strict ? "error" : problem.applied ? "warning" : "warning, edit skipped";
        process.stderr.write(
          `${input}: ${level}: ${problem.id}: ${problem.message}: ${JSON.stringify(problem.anchor)}\n`
        );
      }
      if (strict && problems.length > 0) failed = true;
      if (!structuralOnly) {
        const temp = join(scratch, `${n}-${guide}.md`);
        await writeFile(temp, next);
        const write = runLineBreaks(lineBreaks, ["--write", temp]);
        // A refusal exits 2 and names the file; exit 2 without one (no parser) is no refusal.
        const refusal = write.status === 2 && write.stderr.includes(`${temp}: refusing to write: `);
        if (refusal && !strict) {
          process.stderr.write(
            `warning: ${output}: semantic-line-breaks.ts --write refused it; ${output} holds the structural text, not re-laid out\n${write.stderr.replaceAll(temp, output)}`
          );
          refused = true;
          results.push({ output, text: next });
          continue;
        }
        if (write.status !== 0) {
          const said = `${write.stdout}${write.stderr}`.replaceAll(temp, input);
          const where = refusal ? " (line numbers count the text --structural-only writes)" : "";
          fail(
            `${input}: semantic-line-breaks.ts --write exited ${write.status}${where}\n${said}`,
            write.status
          );
        }
        const check = runLineBreaks(lineBreaks, [temp]);
        if (check.status > 1) {
          fail(
            `${input}: semantic-line-breaks.ts exited ${check.status}\n${check.stdout}${check.stderr}`,
            check.status
          );
        }
        const level = strict ? "error" : "warning";
        for (const finding of check.stdout.split("\n").filter((line) => line !== "")) {
          process.stderr.write(`${level}: ${finding.replace(temp, output)}\n`);
        }
        if (strict && check.status === 1) failed = true;
        next = await readFile(temp, "utf8");
      }
      results.push({ output, text: next });
    }
    if (failed) {
      process.stderr.write("--strict: nothing written\n");
      return 1;
    }
    for (const { output, text } of results) {
      await mkdir(dirname(output), { recursive: true });
      await writeFile(output, text);
    }
    return refused ? 2 : 0;
  } finally {
    await rm(scratch, { recursive: true, force: true });
  }
}

if (import.meta.main) {
  try {
    process.exit(await main(process.argv.slice(2)));
  } catch (error) {
    if (!(error instanceof Failure)) throw error;
    process.stderr.write(error.message);
    process.exit(error.status);
  }
}
